const SETORES_UNIVERSAIS = new Set(["TODOS", "TODAS", "TODAS AS EMPRESAS", "QUALQUER SEGUIMENTO"]);

function getCatalogoCliente(client) {
  if (client.tipo === "publico") return MATERIA_CATALOG;
  return TESES_PRIVADO.filter((t) => SETORES_UNIVERSAIS.has(t.setor) || t.setor === (client.setor || "").toUpperCase());
}

const EMAIL_TEMPLATE = ({ cliente, materias }) =>
  `Prezado(a),\n\n` +
  `Encaminhamos as Propostas de Prestação de Serviço de Assessoria Jurídica relativa à recuperação de valores ao ${cliente} das seguintes matérias:\n\n` +
  materias.map((m) => `- ${m}`).join("\n") +
  `\n\nNos anexamos, constam os documentos da Monteiro e Monteiro Advogados, quais sejam atestados de capacidade, contrato social, documentos e currículos dos sócios, bem como certidões de regularidade.\n\n` +
  `Sem mais para o momento, com nossos cumprimentos de elevada estima e apreço, colocamo-nos à disposição para quaisquer esclarecimentos e dúvidas que surgirem em relação ao que foi apresentado.\n\n` +
  `Grato (a) desde já pela atenção.\n\n` +
  `Atenciosamente,`;

const APRESENTACAO_INSTITUCIONAL =
  `A MONTEIRO E MONTEIRO ADVOGADOS ASSOCIADOS consolidou, ao longo de mais de 30 anos de atuação, posição de destaque entre as maiores bancas de advocacia do País. Conta com escritórios próprios em São Paulo, Florianópolis, Brasília, Recife, Fortaleza, Salvador, Belém e São Luís, além de unidades integradas à REDE MONTEIRO em todo o território nacional, o que assegura atendimento padronizado e de elevado nível técnico em todos os Estados.\n\n` +
  `O escritório atua de forma estratégica, com foco em áreas específicas do Direito, desenvolvendo soluções jurídicas direcionadas e técnicas. Essa especialização permite identificar oportunidades, estruturar teses consistentes e oferecer assessoria qualificada, alinhada às demandas de cada cliente.\n\n` +
  `A carteira de clientes abrange empresas privadas e entidades de classe de diversos segmentos econômicos, como bebidas, veículos, combustíveis, farmacêutico, atacado, varejo e serviços, entre outros.\n\n` +
  `A MONTEIRO E MONTEIRO ADVOGADOS ASSOCIADOS se mantém firme no propósito de oferecer serviços jurídicos especializados com rigor técnico, atualização constante e elevado padrão de excelência.`;

function montarPropostaPrivado(client, materiasSelecionadas, catalogo) {
  const dataHoje = new Date().toLocaleDateString("pt-BR", { day: "2-digit", month: "long", year: "numeric" });
  const itens = materiasSelecionadas
    .map((nome) => catalogo.find((c) => c.nome === nome))
    .filter(Boolean);

  const carta =
    `Recife/PE, ${dataHoje}\n\n` +
    `AO\n${client.nome}\n\n` +
    `Prezado(a),\n\n` +
    `Através da presente, levamos ao conhecimento de V.Sa. nossa proposta para a prestação de serviços jurídicos em defesa dos interesses da empresa, em demanda judicial e/ou administrativa, na conformidade das matérias apresentadas.\n\n` +
    `Com nossos cumprimentos de elevada estima e apreço, colocamo-nos à disposição para quaisquer esclarecimentos e dúvidas que surgirem em relação aos benefícios apresentados.\n\n` +
    `MONTEIRO E MONTEIRO ADVOGADOS ASSOCIADOS`;

  const apresentacao = `APRESENTAÇÃO\n\n${APRESENTACAO_INSTITUCIONAL}`;

  const indice =
    `PROPOSTA DE PRESTAÇÃO DE SERVIÇOS JURÍDICOS\n\n1. OBJETO\n\n` +
    itens.map((it, i) => `1.${i + 1}  ${it.nome}`).join("\n");

  const corpos = itens
    .map((it) => `${it.nome}\n\n${it.corpo || `[Texto detalhado desta tese ainda não cadastrado — hoje disponível apenas: "${it.nota}"]`}`)
    .join("\n\n---\n\n");

  return `${carta}\n\n===\n\n${apresentacao}\n\n===\n\n${indice}\n\n===\n\n${corpos}`;
}

