function pendenciasComerciaisDinamicas(client) {
  const extras = [];
  (client.processos || []).forEach((p) => {
    if (p.materia === "Securitização") {
      const honorariosPendentes =
        p.status === "Pendente pagamento de honorários para Monteiro" ||
        (p.processosCedidos || []).some((pc) => pc.honorariosPagos === "Não");
      if (honorariosPendentes) extras.push("Pendência de pagamento de honorários da Monteiro (Securitização)");
    }
  });
  const contratosComPendenciaDocumental = (client.contratos || []).filter((ctr) =>
    client.tipo === "publico" ? ctr.kitPrefeito === "PENDENTE" : client.tipo === "privado" ? ctr.documentosFiscais === "PENDENTE" : false
  );
  contratosComPendenciaDocumental.forEach((ctr) => {
    const referencia = ctr.numero ? `contrato nº ${ctr.numero}` : "contrato sem número cadastrado";
    extras.push(
      client.tipo === "publico"
        ? `Pendência de documentação — Kit Prefeito (${referencia})`
        : `Pendência de documentos fiscais (${referencia})`
    );
  });
  return [...(client.pendenciaComercial || []), ...extras];
}

function currency(v) {
  return v.toLocaleString("pt-BR", { style: "currency", currency: "BRL", minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function formatarCNPJ(valor) {
  const digitos = String(valor || "").replace(/\D/g, "").slice(0, 14);
  if (digitos.length <= 2) return digitos;
  if (digitos.length <= 5) return `${digitos.slice(0, 2)}.${digitos.slice(2)}`;
  if (digitos.length <= 8) return `${digitos.slice(0, 2)}.${digitos.slice(2, 5)}.${digitos.slice(5)}`;
  if (digitos.length <= 12) return `${digitos.slice(0, 2)}.${digitos.slice(2, 5)}.${digitos.slice(5, 8)}/${digitos.slice(8)}`;
  return `${digitos.slice(0, 2)}.${digitos.slice(2, 5)}.${digitos.slice(5, 8)}/${digitos.slice(8, 12)}-${digitos.slice(12)}`;
}

function parseValorBR(str) {
  if (!str) return 0;
  const limpo = String(str).replace(/[^\d,.-]/g, "");
  if (!limpo) return 0;
  const normalizado = limpo.replace(/\.(?=\d{3}(\D|$))/g, "").replace(",", ".");
  const n = parseFloat(normalizado);
  return isNaN(n) ? 0 : n;
}

const MESES_ABREV = ["jan", "fev", "mar", "abr", "mai", "jun", "jul", "ago", "set", "out", "nov", "dez"];

function preverEntradaValor(mesDeferimento) {
  // mesDeferimento no formato "MM/AAAA"
  const m = /^(\d{1,2})\/(\d{4})$/.exec((mesDeferimento || "").trim());
  if (!m) return "";
  let mes = parseInt(m[1], 10) - 1;
  let ano = parseInt(m[2], 10);
  mes += 2;
  ano += Math.floor(mes / 12);
  mes = mes % 12;
  return `5º dia útil de ${MESES_ABREV[mes]}/${ano}`;
}

const VIGENCIA_OPTIONS = ["12 meses renováveis", "24 meses renováveis", "Por escopo", "Outro"];

function parseDataBR(str) {
  const m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec((str || "").trim());
  if (!m) return null;
  return new Date(parseInt(m[3], 10), parseInt(m[2], 10) - 1, parseInt(m[1], 10));
}

function calcularDataExpiracao(dataAssinatura, vigencia, dataExpiracaoManual, dataAditivo) {
  if (vigencia === "Por escopo") return "Indeterminada";
  if (vigencia === "Outro") return dataExpiracaoManual || "A definir";
  const dataBase = dataAditivo || dataAssinatura;
  const m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec((dataBase || "").trim());
  if (!m) return "A definir (informe a data de assinatura)";
  const dia = parseInt(m[1], 10);
  let mes = parseInt(m[2], 10) - 1;
  let ano = parseInt(m[3], 10);
  const meses = vigencia === "24 meses renováveis" ? 24 : 12;
  mes += meses;
  ano += Math.floor(mes / 12);
  mes = mes % 12;
  const diaTexto = String(dia).padStart(2, "0");
  const mesTexto = String(mes + 1).padStart(2, "0");
  return `${diaTexto}/${mesTexto}/${ano}`;
}

function diasParaVencimento(dataValidadeTexto) {
  const data = parseDataBR(dataValidadeTexto);
  if (!data) return null;
  const hoje = new Date();
  hoje.setHours(0, 0, 0, 0);
  data.setHours(0, 0, 0, 0);
  return Math.round((data - hoje) / (1000 * 60 * 60 * 24));
}

function statusRegularizacaoContrato(ctr) {
  if (!ctr.vigencia || ctr.vigencia === "Por escopo") return null;
  const validade = calcularDataExpiracao(ctr.dataAssinatura, ctr.vigencia, ctr.dataExpiracaoManual, ctr.dataAditivo);
  const dias = diasParaVencimento(validade);
  if (dias === null) return null;
  if (dias < 0 && !ctr.dataAditivo) return { nivel: "critico", texto: "Pendente de regularização (vencido, sem aditivo)" };
  if (dias < 0) return { nivel: "critico", texto: "Vencido" };
  if (dias <= 30) return { nivel: "alerta", texto: `Vence em ${dias} dia${dias !== 1 ? "s" : ""}` };
  return null;
}

function escapeHtml(s) {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function Badge({ children, bg, color }) {
  return (
    <span className="text-xs px-2 py-1 rounded" style={{ background: bg, color }}>
      {children}
    </span>
  );
}

// Badge "sólido" — usado para o status PRINCIPAL de um processo, com mais peso
// visual que os badges secundários (usa a cor forte do status como fundo).
function StatusBadge({ status }) {
  const cor = STATUS_COLOR[status] || { bg: "#EEF0F4", text: "#475569" };
  const critico = cor.text === "#A85A52"; // crítico (desfavorável/urgente) continua com destaque mais forte (negrito)
  return (
    <span
      className="text-xs px-2.5 py-1 rounded"
      style={{ background: cor.bg, color: cor.text, borderLeft: `3px solid ${cor.text}` }}
    >
      {status}
    </span>
  );
}

// Badge "contorno" — usado para marcações secundárias (tipo de ação, situações
// adicionais, alertas de acompanhamento), mais discreto que o status principal.
function OutlineBadge({ children, color }) {
  return (
    <span className="text-xs px-2 py-0.5 rounded" style={{ background: "transparent", color, border: `1px solid ${color}` }}>
      {children}
    </span>
  );
}

// Badge dourado — reservado para "Estratégico", para não competir com as
// cores de status (verde/vermelho/laranja/azul).
function EstrategicoBadge() {
  return (
    <span className="text-xs px-2 py-0.5 rounded font-medium" style={{ background: "transparent", color: GOLD, border: `1px solid ${GOLD}` }}>
      ★ Estratégico
    </span>
  );
}

