function valorPadrao(m) {
  return m.valor ? currency(m.valor) : (m.nota || "");
}

function statusMateria(client, nome) {
  if (client.materias && client.materias[nome]) return client.materias[nome].status; // "monteiro" | "terceiro"
  if ((client.materiasFechadas || []).includes(nome)) return "contratada";
  if (SEM_VALOR_A_RECUPERAR.has(nome)) return "semvalor";
  return "livre";
}

const STATUS_MATERIA_LABEL = {
  livre: { label: "Livre", bg: "#EAF6EE", color: "#1E6B3D" },
  monteiro: { label: "Contratada — Monteiro", bg: "#E6F1FB", color: "#0C447C" },
  terceiro: { label: "Contratada — Terceiro", bg: "#FEF3E2", color: "#93450A" },
  contratada: { label: "Contratada", bg: "#EEF0F4", color: "#475569" },
  semvalor: { label: "Sem valor a recuperar", bg: "#EEF0F4", color: "#6B7280" },
};

function valorPadraoCliente(client, m) {
  const dados = client.materias && client.materias[m.nome];
  if (dados && dados.acao) {
    const v = dados.acao.valorExecutado ?? dados.acao.valorEstimado ?? dados.acao.valorCausa;
    if (v) return currency(v);
  }
  return valorPadrao(m);
}

function formatarContratoTexto(contrato) {
  if (!contrato) return "";
  let t = contrato.numero ? `nº ${contrato.numero}, assinado em ${contrato.assinadoEm}` : `assinado em ${contrato.assinadoEm}`;
  if (contrato.procuracaoEm) t += `, procuração em ${contrato.procuracaoEm}`;
  if (contrato.observacao) t += ` (${contrato.observacao})`;
  return t;
}

function formatarHistoricoTexto(historico) {
  if (!historico) return "";
  return historico.map((h) => `${h.data ? h.data + " — " : ""}${h.texto}`).join("\n");
}

function acaoEdicaoInicial(client, nome) {
  const base = client.materias && client.materias[nome];
  if (!base) {
    return { ativa: false, tipo: "monteiro", patronos: "", processo: "", periodo: "", contrato: "", historico: "" };
  }
  return {
    ativa: true,
    tipo: base.status,
    patronos: base.acao.patronos || "",
    processo: base.acao.processo || "",
    periodo: base.acao.periodo || "",
    contrato: formatarContratoTexto(base.acao.contrato),
    historico: formatarHistoricoTexto(base.acao.historico),
  };
}

function statusDeAcaoEditavel(nome, ac) {
  if (ac.ativa) return ac.tipo === "monteiro" ? "monteiro" : "terceiro";
  if (SEM_VALOR_A_RECUPERAR.has(nome)) return "semvalor";
  return "livre";
}

function DiagnosticoModal({ client, onClose, onGerarProposta }) {
  const [valores, setValores] = useState({});
  const [acoes, setAcoes] = useState({});
  const [carregando, setCarregando] = useState(true);
  const [status, setStatus] = useState("");
  const [abertos, setAbertos] = useState({});
  const [materiasSelecionadas, setMateriasSelecionadas] = useState({});
  const modoProposta = true;
  const tituloProposta = client.tipo === "privado" || client.tipo === "entidade";
  const chave = `diagnostico:${client.id}`;
  const catalogo = getCatalogoCliente(client);

  useEffect(() => {
    (async () => {
      const valoresDefault = {};
      const acoesDefault = {};
      catalogo.forEach((m) => {
        valoresDefault[m.nome] = valorPadraoCliente(client, m);
        acoesDefault[m.nome] = acaoEdicaoInicial(client, m.nome);
      });
      try {
        const res = await window.storage.get(chave, false);
        const salvos = res ? JSON.parse(res.value) : {};
        setValores({ ...valoresDefault, ...(salvos.valores || {}) });
        setAcoes({ ...acoesDefault, ...(salvos.acoes || {}) });
      } catch (e) {
        setValores(valoresDefault);
        setAcoes(acoesDefault);
      }
      setCarregando(false);
    })();
  }, []);

  const atualizarValor = (nome, texto) => {
    setValores((prev) => ({ ...prev, [nome]: texto }));
  };

  const atualizarAcao = (nome, campo, texto) => {
    setAcoes((prev) => ({ ...prev, [nome]: { ...prev[nome], [campo]: texto } }));
  };

  const toggleAberto = (nome) => {
    setAbertos((prev) => ({ ...prev, [nome]: !prev[nome] }));
  };

  const salvar = async () => {
    try {
      await window.storage.set(chave, JSON.stringify({ valores, acoes }), false);
      setStatus("Versão salva.");
    } catch (e) {
      setStatus("Não foi possível salvar agora.");
    }
    setTimeout(() => setStatus(""), 2500);
  };

  const materiasLivresCount = catalogo.filter((m) => statusDeAcaoEditavel(m.nome, acoes[m.nome] || { ativa: false }) === "livre").length;

  const montarTexto = () => {
    const linhas = catalogo.map((m) => {
      const ac = acoes[m.nome] || { ativa: false };
      const tag = STATUS_MATERIA_LABEL[statusDeAcaoEditavel(m.nome, ac)].label;
      let bloco = `${m.nome} [${tag}]: ${valores[m.nome] || ""}`;
      if (ac.ativa) {
        if (ac.patronos) bloco += `\n  Patrono(s): ${ac.patronos}`;
        if (ac.processo) bloco += `\n  Processo: ${ac.processo}`;
        if (ac.periodo) bloco += `\n  Período: ${ac.periodo}`;
        if (ac.contrato) bloco += `\n  Contrato: ${ac.contrato}`;
        if (ac.historico) bloco += `\n  Histórico:\n  ${ac.historico.split("\n").join("\n  ")}`;
      }
      return bloco;
    }).join("\n\n");
    return `Diagnóstico comercial — ${client.nome}\n\n${linhas}`;
  };

  const baixarWord = () => {
    const html = `<html><meta charset="utf-8"><body><pre style="font-family:Arial,sans-serif;font-size:13px;white-space:pre-wrap;">${escapeHtml(montarTexto())}</pre></body></html>`;
    const blob = new Blob([html], { type: "application/msword" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `Diagnostico - ${client.nome}.doc`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const baixarPdf = () => {
    const w = window.open("", "_blank");
    if (!w) {
      setStatus("Não foi possível abrir a janela de impressão — permita pop-ups e tente novamente.");
      setTimeout(() => setStatus(""), 3500);
      return;
    }
    w.document.write(`<html><head><title>Diagnóstico - ${client.nome}</title></head><body><pre style="font-family:Arial,sans-serif;font-size:13px;white-space:pre-wrap;">${escapeHtml(montarTexto())}</pre></body></html>`);
    w.document.close();
    w.focus();
    w.print();
  };

  if (carregando) {
    return (
      <Modal title={tituloProposta ? "Proposta Comercial" : "Diagnóstico comercial"} onClose={onClose} wide>
        <p className="text-sm" style={{ color: "#6B7280" }}>Carregando última versão...</p>
      </Modal>
    );
  }

  return (
    <Modal title={tituloProposta ? "Proposta Comercial" : "Diagnóstico comercial"} onClose={onClose} wide>
      {client.tipo !== "publico" && (
      <>
      <p className="text-xs mb-3" style={{ color: "#6B7280" }}>
        {materiasLivresCount} matéria{materiasLivresCount !== 1 ? "s" : ""} livre{materiasLivresCount !== 1 ? "s" : ""} de {catalogo.length} no total
      </p>

      <div className="space-y-2 mb-4">
        {catalogo.map((m, i) => {
          const ac = acoes[m.nome] || { ativa: false, tipo: "monteiro", patronos: "", processo: "", periodo: "", contrato: "", historico: "" };
          const st = statusDeAcaoEditavel(m.nome, ac);
          if (modoProposta && st !== "livre") return null;
          const cor = STATUS_MATERIA_LABEL[st];
          const aberto = abertos[m.nome];

          return (
            <div key={i} className="border rounded px-3 py-2" style={{ borderColor: "#DCE3E0" }}>
              <div className="flex items-center justify-between mb-1">
                <div className="flex items-center gap-2">
                  <span className="text-sm" style={{ color: INK }}>{m.nome}</span>
                  {!(modoProposta && st === "livre") && (
                    <Badge bg={cor.bg} color={cor.color}>{cor.label}</Badge>
                  )}
                </div>
                <div className="flex items-center gap-2">
                  {modoProposta ? (
                    <label className="flex items-center gap-1.5 text-xs" style={{ color: "#374151" }}>
                      <input
                        type="checkbox"
                        checked={!!materiasSelecionadas[m.nome]}
                        onChange={(e) => setMateriasSelecionadas((prev) => ({ ...prev, [m.nome]: e.target.checked }))}
                      />
                      Incluir na proposta
                    </label>
                  ) : (
                    <button onClick={() => toggleAberto(m.nome)} className="flex items-center gap-1 text-xs" style={{ color: "#6B7280" }}>
                      {ac.ativa ? "Editar ação" : "Adicionar ação"}
                      <ChevronDown size={13} style={{ transform: aberto ? "rotate(180deg)" : "none", transition: "transform .15s" }} />
                    </button>
                  )}
                </div>
              </div>

              {!modoProposta && (
                <input
                  value={valores[m.nome] ?? ""}
                  onChange={(e) => atualizarValor(m.nome, e.target.value)}
                  className="w-full text-xs border rounded px-2 py-1"
                  style={{ borderColor: "#DCE3E0", color: "#6B7280" }}
                />
              )}

              {aberto && (
                <div className="mt-2 pt-2 border-t space-y-2" style={{ borderColor: "#DCE3E0" }}>
                  <label className="flex items-center gap-2 text-xs" style={{ color: "#374151" }}>
                    <input
                      type="checkbox"
                      checked={ac.ativa}
                      onChange={(e) => atualizarAcao(m.nome, "ativa", e.target.checked)}
                    />
                    Esta matéria tem ação
                  </label>

                  {ac.ativa && (
                    <>
                      <div className="flex items-center gap-2">
                        <span className="text-xs" style={{ color: "#6B7280" }}>Contratada por:</span>
                        <select
                          value={ac.tipo}
                          onChange={(e) => atualizarAcao(m.nome, "tipo", e.target.value)}
                          className="text-xs border rounded px-2 py-1"
                          style={{ borderColor: "#DCE3E0" }}
                        >
                          <option value="monteiro">Monteiro</option>
                          <option value="terceiro">Terceiro</option>
                        </select>
                      </div>
                      <div>
                        <p className="text-xs mb-1" style={{ color: "#6B7280" }}>Patrono(s)</p>
                        <input value={ac.patronos} onChange={(e) => atualizarAcao(m.nome, "patronos", e.target.value)} className="w-full text-xs border rounded px-2 py-1" style={{ borderColor: "#DCE3E0" }} />
                      </div>
                      <div>
                        <p className="text-xs mb-1" style={{ color: "#6B7280" }}>Processo</p>
                        <input value={ac.processo} onChange={(e) => atualizarAcao(m.nome, "processo", e.target.value)} className="w-full text-xs border rounded px-2 py-1" style={{ borderColor: "#DCE3E0" }} />
                      </div>
                      <div>
                        <p className="text-xs mb-1" style={{ color: "#6B7280" }}>Período</p>
                        <input value={ac.periodo} onChange={(e) => atualizarAcao(m.nome, "periodo", e.target.value)} className="w-full text-xs border rounded px-2 py-1" style={{ borderColor: "#DCE3E0" }} />
                      </div>
                      <div>
                        <p className="text-xs mb-1" style={{ color: "#6B7280" }}>Contrato</p>
                        <input value={ac.contrato} onChange={(e) => atualizarAcao(m.nome, "contrato", e.target.value)} className="w-full text-xs border rounded px-2 py-1" style={{ borderColor: "#DCE3E0" }} />
                      </div>
                      <div>
                        <p className="text-xs mb-1" style={{ color: "#6B7280" }}>Histórico (uma movimentação por linha)</p>
                        <textarea
                          value={ac.historico}
                          onChange={(e) => atualizarAcao(m.nome, "historico", e.target.value)}
                          rows={4}
                          className="w-full text-xs border rounded px-2 py-1.5"
                          style={{ borderColor: "#DCE3E0" }}
                        />
                      </div>
                    </>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
      </>
      )}

      <div className="flex flex-wrap items-center gap-2 pt-3 border-t" style={{ borderColor: "#DCE3E0" }}>
        {!modoProposta && (
          <button onClick={salvar} className="flex items-center gap-1.5 text-sm px-3 py-1.5 rounded border" style={{ borderColor: "#DCE3E0" }}>
            <Check size={15} /> Salvar versão
          </button>
        )}
        <button onClick={baixarWord} className="flex items-center gap-1.5 text-sm px-3 py-1.5 rounded text-white" style={{ background: INK }}>
          <FileText size={15} /> Gerar Word
        </button>
        <button onClick={baixarPdf} className="flex items-center gap-1.5 text-sm px-3 py-1.5 rounded text-white" style={{ background: INK }}>
          <FileText size={15} /> Gerar PDF
        </button>
        <button
          onClick={() => onGerarProposta(
            client.tipo === "publico"
              ? catalogo.filter((m) => statusDeAcaoEditavel(m.nome, acoes[m.nome] || { ativa: false }) === "livre").map((m) => m.nome)
              : catalogo.filter((m) => materiasSelecionadas[m.nome]).map((m) => m.nome)
          )}
          className="flex items-center gap-1.5 text-sm px-3 py-1.5 rounded text-white"
          style={{ background: "#1E6B3D" }}
        >
          <Mail size={15} /> Enviar proposta
        </button>
        {status && <span className="text-xs" style={{ color: "#6B7280" }}>{status}</span>}
      </div>
    </Modal>
  );
}

function ProposalModal({ client, preselect, onClose }) {
  const [selected, setSelected] = useState(preselect || []);
  const [body, setBody] = useState(EMAIL_TEMPLATE({ cliente: `${client.nome} - ${client.uf}`, materias: preselect || [] }));
  const [status, setStatus] = useState("");
  const catalogo = getCatalogoCliente(client);

  const toggle = (m) => {
    const next = selected.includes(m) ? selected.filter((x) => x !== m) : [...selected, m];
    setSelected(next);
    setBody(EMAIL_TEMPLATE({ cliente: `${client.nome} - ${client.uf}`, materias: next }));
  };

  const destinatario = client.contatos[0]?.email || "";
  const assunto = `Proposta de atuação — ${client.nome}`;
  const ccProposta = client.tipo === "publico" ? "contratospublicos@monteiro.adv.br" : "";
  const gmailUrl = `https://mail.google.com/mail/?view=cm&fs=1&to=${encodeURIComponent(destinatario)}&cc=${encodeURIComponent(ccProposta)}&su=${encodeURIComponent(assunto)}&body=${encodeURIComponent(body)}`;

  const baixarWord = () => {
    const texto = montarPropostaPrivado(client, selected, catalogo);
    const html = `<html><meta charset="utf-8"><body><pre style="font-family:Arial,sans-serif;font-size:13px;white-space:pre-wrap;">${escapeHtml(texto)}</pre></body></html>`;
    const blob = new Blob([html], { type: "application/msword" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `Proposta - ${client.nome}.doc`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const baixarPdf = () => {
    const texto = montarPropostaPrivado(client, selected, catalogo);
    const w = window.open("", "_blank");
    if (!w) {
      setStatus("Não foi possível abrir a janela de impressão — permita pop-ups e tente novamente.");
      setTimeout(() => setStatus(""), 3500);
      return;
    }
    w.document.write(`<html><head><title>Proposta - ${client.nome}</title></head><body><pre style="font-family:Arial,sans-serif;font-size:13px;white-space:pre-wrap;">${escapeHtml(texto)}</pre></body></html>`);
    w.document.close();
    w.focus();
    w.print();
  };

  return (
    <Modal title={`Gerar proposta — ${client.nome}`} onClose={onClose} wide>
      <p className="text-xs mb-2" style={{ color: "#6B7280" }}>Selecione as matérias a incluir na proposta</p>
      <div className="flex flex-wrap gap-2 mb-4">
        {catalogo.filter((mat) => !SEM_VALOR_A_RECUPERAR.has(mat.nome)).map((mat) => {
          const m = mat.nome;
          const active = selected.includes(m);
          return (
            <button
              key={m}
              onClick={() => toggle(m)}
              className="text-xs px-3 py-1.5 rounded border flex items-center gap-1"
              style={{
                borderColor: active ? GOLD : "#DCE3E0",
                background: active ? "#FBF1E1" : "white",
                color: active ? "#93450A" : "#374151",
              }}
            >
              {active && <Check size={12} />} {m}
            </button>
          );
        })}
      </div>

      {client.tipo === "privado" && (
        <div className="flex flex-wrap items-center gap-2 mb-4 pb-4 border-b" style={{ borderColor: "#DCE3E0" }}>
          <button
            onClick={baixarWord}
            disabled={selected.length === 0}
            className="flex items-center gap-1.5 text-sm px-3 py-1.5 rounded text-white"
            style={{ background: selected.length ? INK : "#C4C4C4" }}
          >
            <FileText size={15} /> Gerar Word (documento completo)
          </button>
          <button
            onClick={baixarPdf}
            disabled={selected.length === 0}
            className="flex items-center gap-1.5 text-sm px-3 py-1.5 rounded text-white"
            style={{ background: selected.length ? INK : "#C4C4C4" }}
          >
            <FileText size={15} /> Gerar PDF (documento completo)
          </button>
          {status && <span className="text-xs" style={{ color: "#6B7280" }}>{status}</span>}
        </div>
      )}

      <p className="text-xs mb-1" style={{ color: "#6B7280" }}>E-mail (editável antes de enviar)</p>
      <textarea
        value={body}
        onChange={(e) => setBody(e.target.value)}
        rows={9}
        className="w-full text-sm border rounded p-3 mb-3"
        style={{ borderColor: "#DCE3E0" }}
      />
      <a
        href={gmailUrl}
        target="_blank"
        rel="noreferrer"
        className="inline-flex items-center gap-1.5 text-sm px-3 py-1.5 rounded text-white"
        style={{ background: selected.length ? GOLD : "#C4C4C4", pointerEvents: selected.length ? "auto" : "none" }}
      >
        <Mail size={15} /> Abrir no Gmail
      </a>
    </Modal>
  );
}

function MultiSelectFilter({ label, options, groupedOptions, selected, onChange }) {
  const [open, setOpen] = useState(false);
  const toggleOption = (opt) => {
    onChange(selected.includes(opt) ? selected.filter((x) => x !== opt) : [...selected, opt]);
  };
  return (
    <div className="relative">
      <button
        onClick={() => setOpen(!open)}
        className="border rounded px-2 py-1.5 text-sm flex items-center gap-1.5"
        style={{ borderColor: selected.length ? GOLD : "#DCE3E0", color: selected.length ? "#93450A" : "#374151" }}
      >
        {label}{selected.length > 0 ? ` (${selected.length})` : ""}
        <ChevronDown size={14} style={{ color: "#9CA3AF" }} />
      </button>
      {open && (
        <div className="absolute z-10 mt-1 bg-white border rounded shadow-sm p-2 min-w-[170px] max-h-80 overflow-y-auto" style={{ borderColor: "#DCE3E0" }}>
          {groupedOptions ? (
            Object.entries(groupedOptions).map(([grupo, opts]) => (
              opts.length > 0 && (
                <div key={grupo} className="mb-1">
                  <p className="text-xs px-1.5 pt-1 pb-0.5" style={{ color: "#9CA3AF" }}>{grupo}</p>
                  {opts.map((opt) => (
                    <label key={opt} className="flex items-center gap-2 text-sm px-1.5 py-1 cursor-pointer hover:bg-gray-50 rounded">
                      <input type="checkbox" checked={selected.includes(opt)} onChange={() => toggleOption(opt)} />
                      {opt}
                    </label>
                  ))}
                </div>
              )
            ))
          ) : (
            options.map((opt) => (
              <label key={opt} className="flex items-center gap-2 text-sm px-1.5 py-1 cursor-pointer hover:bg-gray-50 rounded">
                <input type="checkbox" checked={selected.includes(opt)} onChange={() => toggleOption(opt)} />
                {opt}
              </label>
            ))
          )}
          <div className="flex justify-between mt-1 pt-1 border-t" style={{ borderColor: "#DCE3E0" }}>
            <button onClick={() => onChange([])} className="text-xs px-1.5 py-1" style={{ color: "#6B7280" }}>Limpar</button>
            <button onClick={() => setOpen(false)} className="text-xs px-1.5 py-1" style={{ color: INK }}>Fechar</button>
          </div>
        </div>
      )}
    </div>
  );
}

function ClientList({ tipo, setTipo, onSelect }) {
  const [estado, setEstado] = useState([]);
  const [responsavel, setResponsavel] = useState([]);
  const [pendencia, setPendencia] = useState([]);
  const [busca, setBusca] = useState("");

  const base = CLIENTS.filter((c) => c.tipo === tipo);
  const estados = Array.from(new Set(base.map((c) => c.uf)));

  const filtered = base.filter((c) => {
    if (estado.length && !estado.includes(c.uf)) return false;
    if (responsavel.length && !responsavel.includes(c.responsavel)) return false;
    if (pendencia.length) {
      const matchC = pendencia.includes("Comercial") && pendenciasComerciaisDinamicas(c).length > 0;
      const matchP = pendencia.includes("Processual") && c.pendenciaProcessual.length > 0;
      if (!(matchC || matchP)) return false;
    }
    if (busca && !c.nome.toLowerCase().includes(busca.toLowerCase())) return false;
    return true;
  });

  return (
    <div className="max-w-3xl mx-auto py-8 px-4">
      <div className="mb-6 flex items-start justify-between">
        <div>
          <h1 className="text-xl" style={{ color: INK, fontFamily: TITULO_FONT_FAMILY, fontWeight: "bold" }}>Portal Comercial</h1>
          <div className="w-10 h-0.5 mt-2" style={{ background: GOLD }} />
        </div>
      </div>

      <div className="flex gap-1 mb-5 w-fit p-1 rounded" style={{ background: "#E2E9E6" }}>
        {["publico", "privado", "entidade"].map((t) => (
          <button
            key={t}
            onClick={() => setTipo(t)}
            className="text-sm px-4 py-1.5 rounded"
            style={{
              background: tipo === t ? "white" : "transparent",
              color: tipo === t ? INK : "#6B7280",
              boxShadow: tipo === t ? "0 0 0 1px #DCE3E0" : "none",
            }}
          >
            {t === "publico" ? "Público" : t === "privado" ? "Privado" : "Entidades de classe"}
          </button>
        ))}
      </div>

      <div className="flex flex-wrap gap-2 mb-5">
        <MultiSelectFilter label="Estado" options={estados} selected={estado} onChange={setEstado} />
        {tipo === "publico" && (
          <MultiSelectFilter label="Responsável" options={RESPONSAVEL_OPTIONS} selected={responsavel} onChange={setResponsavel} />
        )}
        <MultiSelectFilter label="Pendência" options={["Comercial", "Processual"]} selected={pendencia} onChange={setPendencia} />
        <div className="flex items-center border rounded px-2 flex-1 min-w-[180px]" style={{ borderColor: "#DCE3E0" }}>
          <Search size={15} style={{ color: "#9CA3AF" }} />
          <input
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            placeholder="Buscar cliente"
            className="text-sm px-2 py-1.5 flex-1 outline-none"
          />
        </div>
      </div>

      <div className="flex flex-col gap-2">
        {filtered.map((c) => (
          <button
            key={c.id}
            onClick={() => onSelect(c.id)}
            className="flex items-center justify-between border rounded-lg px-4 py-3 bg-white text-left hover:shadow-sm transition"
            style={{ borderColor: "#DCE3E0" }}
          >
            <div className="flex items-center gap-3">
              {c.tipo === "publico" ? (
                <Landmark size={20} style={{ color: "#6B7280" }} />
              ) : c.tipo === "entidade" ? (
                <Users size={20} style={{ color: "#6B7280" }} />
              ) : (
                <Building2 size={20} style={{ color: "#6B7280" }} />
              )}
              <div>
                <p className="text-sm font-medium flex items-center gap-1.5" style={{ color: INK }}>
                  {c.nome}
                  {(c.processos || []).some((p) => p.estrategico) && (
                    <EstrategicoBadge />
                  )}
                </p>
                <p className="text-xs" style={{ color: "#6B7280" }}>{c.esfera} · {c.uf}</p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              {pendenciasComerciaisDinamicas(c).length > 0 && (
                <Badge bg="#FEF3E2" color="#93450A">{pendenciasComerciaisDinamicas(c).length} comercial</Badge>
              )}
              {c.pendenciaProcessual.length > 0 && (
                <Badge bg="#FDECEC" color="#A85A52">{c.pendenciaProcessual.length} processual</Badge>
              )}
              <ChevronRight size={18} style={{ color: "#9CA3AF" }} />
            </div>
          </button>
        ))}
        {filtered.length === 0 && (
          <p className="text-sm text-center py-8" style={{ color: "#6B7280" }}>Nenhum cliente encontrado com esses filtros.</p>
        )}
      </div>
    </div>
  );
}

