                              <input placeholder="Valor (ex.: R$ 740.000,00)" value={novoPrecatorio.valor} onChange={(e) => setNovoPrecatorio({ ...novoPrecatorio, valor: e.target.value })} className="text-xs border rounded px-2 py-1" style={{ borderColor: "#DCE3E0" }} />
