                                  <select value={rascunhoProcessoCedido.objeto} onChange={(e) => setRascunhoProcessoCedido({ ...rascunhoProcessoCedido, objeto: e.target.value })} className="text-xs border rounded px-2 py-1" style={{ borderColor: "#DCE3E0" }}>
                                    {OBJETO_SECURITIZACAO_OPTIONS.map((op) => <option key={op} value={op}>{op}</option>)}
                                  </select>
