                                    {procItem.honorarios && ` · Honorários da Monteiro: ${procItem.honorarios === "Outro" ? (procItem.honorariosManual || "Outro") : procItem.honorarios}`}
                                    {procItem.honorarios && ` · Honorários pagos: ${procItem.honorariosPagos || "Não"}`}
